, vanuit zijn positie als arts en gevangene.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.donner.nl/producten/eindstation-auschwitz-9789029093606/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p422983578"],"checked_at":"2026-11-02T21:06:36.091Z","reference":"work:1619","note":"Exact KB ISBN9789029093606 person p06852725X explicitly lists Wind,Eddy de and Wind,Eliazar de as aliases of Eduard de Wind. Donner exact2020NLhardback confirms public Eddy credit and same camp memoir. No new author or Work.","canonical_name_resolution":"Exact KB ISBN9789029093606 person p06852725X explicitly lists Wind,Eddy de and Wind,Eliazar de as aliases of Eduard de Wind. Donner exact2020NLhardback confirms public Eddy credit and same camp memoir. No new author or Work."},{"type":"original_substantive_source_review","review":"content-review-016.json","sources":["https://www.donner.nl/producten/eindstation-auschwitz-9789029093606/","https://openlibrary.org/works/OL34311013W","https://data.bibliotheken.nl/id/nbt/p422983578"]},{"type":"cover_front_review","cover_id":13188943,"sha256":"b70a4a064c52f230854fc63af4c5ab95988b0cd2041d435df06c37d360023fd4","reference":"cover-semantic-review-002.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T21:06:36.091Z","review_batch":"nl-scale-20261102-014"}},{"ref":"m2","relation":"catalog_edition_metadata","key":{"edition_id":1749},"before":null,"after":{"edition_id":1749,"work_id":1619,"bound_author_id":865,"bound_title":"Eindstation Auschwitz","bound_language":"dut","bound_isbn13":"9789029093606","format":"hardcover","cover_url":"https://covers.openlibrary.org/b/id/13188943-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/13188943-M.jpg?default=false"