ha256":"7f45914a09af1bbb71c532861b731a363cae9c7384b66e12b2b4c504d6715705","reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Hermann Hesse; De steppewolf. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"review_status":"approved","reviewed_at":"2026-11-02T21:06:36.091Z","review_batch":"nl-scale-20261102-014"}},{"ref":"d4","relation":"catalog_work_descriptions","key":{"work_id":2399,"language":"nl"},"before":null,"after":{"work_id":2399,"language":"nl","bound_author_id":73,"text":"Hoe kan het heelal zijn ontstaan en wat bedoelen we wanneer we spreken over werkelijkheid? Het grote ontwerp verkent die vragen aan de hand van natuurkundige modellen. Daarbij komen onder meer verschillende mogelijke heelallen, de rol van waarneming en pogingen tot een overkoepelende theorie aan bod. De auteurs bespreken wat zulke benaderingen kunnen betekenen voor traditionele verklaringen van de kosmos. Het boek presenteert hun kijk op deze wetenschappelijke en filosofische vraagstukken, zonder dat de lezer zelf de wiskundige uitwerking hoeft te volgen.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.penguin.co.uk/books/393369/the-grand-design-by-stephen-hawking-with-leonard-mlodinow/9780553819229","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p327944463"],"checked_at":"2026-11-02T21:06:36.091Z","reference":"work:2399","note":"Same TheGrandDesign non-fiction Work. Primary publisher explicitly credits Stephen Hawking and Leonard Mlodinow, not a synthetic combined person. Exact Dutch paperback9789035131873 is independently bound by KB p327944463. Scientific models remain attributed to the book, no automatically approved taste features.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-022.json","sources":["https://www.penguin.co.uk/books/393369/the-grand-design-by-stephen-hawking-with-leonard-mlodinow/9780553819229","https://openlibrary.org/works/OL15367338W","https://data.bibliotheken.nl/id/nbt/p327944463"]},{"type":"cover_front_review","cover_id":6785774,"sha256":"0e48a399a18ca90841d95c9baa0f167e0b23e41932ef1e87eeb0764b0982b2da","reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-002.jpg. Stephen Hawking AND Leonard Mlodinow; Het grote ontwerp; Bert Bakker. Mlodinow coauthor must not be mistaken for translator. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T21:06:36.091Z","review_batch":"nl-scale-20261102-014"}},{"ref":"m4","relation":"catalog_edition_metadata","key":{"edition_id":2625},"before":null,"after":{"edition_id":2625,"work_id":2399,"bound_author_id":73,"bound_title":"Het Grote Ontwerp","bound_language":"dut","bound_isbn13":"9789035131873","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/6785774-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/6785774-M.jpg?default=false","evidence_url":"https://data.bibliotheken.nl/id/nbt/p327944463","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p327944463"],"checked_at":"2026-11-02T21:06:36.091Z","reference":"work:2399","note":"Same TheGrandDesign non-fiction Work. Primary publisher explicitly credits Stephen Hawking and Leonard Mlodinow, not a synthetic combined person. Exact Dutch paperback9789035131873 is independently bound by KB p327944463. Scientific models remain attributed to the book, no automatically approved taste features.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-022.json","sources":["https://www.penguin.co.uk/books/393369/the-grand-design-by-stephen-hawking-with-leonard-mlodinow/9780553819229","https://openlibrary.org/works/OL15367338W","https://data.bibliotheken.nl/id/nbt/p327944463"]},{"type":"cover_front_review","cover_id":6785774,"sha256":"0e48a399a18ca90841d95c9baa0f167e0b23e41932ef1e87eeb0764b0982b2da","reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-002.jpg. Stephen Hawking AND Leonard Mlodinow; Het grote ontwerp; Bert Bakker. Mlodinow coauthor must not be mistaken for translator. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"review_status":"approved","reviewed_at":"2026-11-02T21:06:36.091Z","review_batch":"nl-scale-20261102-014"}},{"ref":"d5","relation":"catalog_work_descriptions","key":{"work_id":3376,"language":"nl"},"before":null,"after":{"work_id":3376,"language":"nl","bound_author_id":22,"text":"Een jonge heks begint aan haar opleiding en verwacht vooral spreuken en bijzondere krachten te leren kennen. In plaats daarvan krijgt ze te maken met huishoudelijk werk en lastige geiten. Terwijl zij probeert te begrijpen wat heks zijn werkelijk inhoudt, wordt ze achtervolgd door een wezen zonder eigen lichaam. Zelfs ervaren heksen en haar kleine, strijdlustige bondgenoten kunnen het probleem niet eenvoudig voor haar oplossen. Haar opleiding krijgt daarmee een andere betekenis: zij zal ook op haar eigen innerlijke kracht moeten leren vertrouwen.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL453737W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p296390488"],"checked_at":"2026-11-02T21:06:36.091Z","reference":"work:3376","note":"Exact KB person p07381993X and source author OL25712A share Q46248, VIAF76382712 and ISNI0000000121401960. Terry and Terence David John refer to this authority, not equal-name inference. Exact Dutch hardcover9789022543122, existing A Hat Full of Sky Work retained.","canonical_name_resolution":"Exact KB person p07381993X and source author OL25712A share Q46248, VIAF76382712 and ISNI0000000121401960. Terry and Terence David John refer to this authority, not equal-name inference. Exact Dutch hardcover9789022543122, existing A Hat Full of Sky Work retained."},{"type":"original_substantive_source_review","review":"content-review-022.json","sources":["https://openlibrary.org/works/OL453737W","https://data.bibliotheken.nl/id/nbt/p296390488"]},{"type":"cover_front_review","cover_id":14647206,"sha256":"e53a05941868259607f0c966f295182aa9281ec8719112485346f9ae3f2e9121","reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T21:06:36.091Z","review_batch":"nl-scale-20261102-014"}},{"ref":"m5","relation":"catalog_edition_metadata","key":{"edition_id":3535},"before":null,"after":{"edition_id":3535,"work_id":3376,"bound_author_id":22,"bound_title":"Een Hoed Van Lucht","bound_language":"dut","bound_isbn13":"9789022543122","format":"hardcover","cover_url":"https://covers.openlibrary.org/b/id/14647206-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/14647206-M.jpg?default=false","evidence_url":"https://data.bibliotheken.nl/id/nbt/p296390488","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p296390488"],"checked_at":"2026-11-02T21:06:36.091Z","reference":"work:3376","note":"Exact KB person p07381993X and source author OL25712A share Q46248, VIAF76382712 and ISNI0000000121401960. Terry and Terence David John refer to this autho